record.field:
for rec in self:
    is_paid = rec.x_studio_payment_state in ('paid', 'in_payment')
    rec['x_studio_is_overdue'] = bool(rec.x_studio_date and rec.x_studio_date < datetime.date.today() and not is_paid)

for rec in self:
    fee = 0.0
    inv = rec.x_studio_invoice_id
    if inv:
        late_lines = inv.invoice_line_ids.filtered(lambda l: 'Late Payment' in (l.name or '') and (rec.x_name in (l.name or '') or len(rec.x_studio_contract_id.x_studio_installment_ids.filtered(lambda i: i.x_studio_invoice_id == inv)) == 1))
        if late_lines:
            fee = sum(l.price_unit for l in late_lines)
        elif rec.x_studio_contract_id and rec.x_studio_contract_id.x_studio_lease_plan:
            inv_date = inv.invoice_date or datetime.date.today()
            if rec.x_studio_date and rec.x_studio_date < inv_date:
                plan = rec.x_studio_contract_id.x_studio_lease_plan
                fee_type = plan.x_studio_late_fee_type
                if fee_type == 'Fixed Amount':
                    fee = plan.x_studio_late_fee or 0.0
                elif fee_type == 'Percentage':
                    fee = (rec.x_studio_amount or 0.0) * ((plan.x_studio_late_fee_percentage or 0.0) / 100.0)
    elif rec.x_studio_is_overdue and rec.x_studio_contract_id and rec.x_studio_contract_id.x_studio_lease_plan:
        plan = rec.x_studio_contract_id.x_studio_lease_plan
        fee_type = plan.x_studio_late_fee_type
        if fee_type == 'Fixed Amount':
            fee = plan.x_studio_late_fee or 0.0
        elif fee_type == 'Percentage':
            fee = (rec.x_studio_amount or 0.0) * ((plan.x_studio_late_fee_percentage or 0.0) / 100.0)
    rec['x_studio_late_fee_amount'] = fee

for rec in self:
    inv = rec.x_studio_deposit_invoice_id
    rec['x_studio_deposit_paid'] = bool(inv and inv.payment_state in ('paid', 'in_payment'))

for rec in self:
    drafts = rec.x_studio_installment_ids.filtered(lambda i: i.x_studio_status == 'Draft')
    rec['x_studio_has_draft_installments'] = bool(drafts)

for rec in self:
    invoices = rec.x_studio_installment_ids.mapped('x_studio_invoice_id')
    if rec.x_studio_deposit_invoice_id:
        invoices |= rec.x_studio_deposit_invoice_id
    if rec.x_studio_return_invoice_id:
        invoices |= rec.x_studio_return_invoice_id
    has_draft_inst = bool(rec.x_studio_installment_ids.filtered(lambda i: i.x_studio_status == 'Draft'))
    unpaid_invs = invoices.filtered(lambda inv: inv.payment_state not in ('paid', 'in_payment'))
    rec['x_studio_all_invoices_paid'] = bool(invoices and not has_draft_inst and not unpaid_invs)

for rec in self:
    invoices = rec.x_studio_installment_ids.mapped('x_studio_invoice_id')
    if rec.x_studio_deposit_invoice_id:
        invoices |= rec.x_studio_deposit_invoice_id
    if rec.x_studio_return_invoice_id:
        invoices |= rec.x_studio_return_invoice_id
    rec['x_studio_invoice_count'] = len(invoices)
